function memoize(fn) {
  return fn;
}

solutionCodeJson.code:
// Bài 9.4 — A giữ danh sách tham số, R giữ kiểu trả về: hàm bọc có ĐÚNG chữ ký của hàm gốc
function memoize(fn) {
  const cache = new Map();
  let count = 0;
  const wrapped = (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    count++;
    const result = fn(...args);                 // ném lỗi ⇒ dừng ở đây, không có gì được nhớ
    cache.set(key, result);
    return result;
  };
  wrapped.calls = () => count;
  return wrapped;
}

